  assert.strictEqual(highlight('aXa \u00e0', 'a'), '[[a]]X[[a]] [[\u00e0]]');
  assert.strictEqual(highlight('\u00c9COLE \u00e9cole', 'ecole'), '[[\u00c9COLE]] [[\u00e9cole]]');
